sp_widget.css:
.info-box {
    border: 1px solid #ccc;
    padding: 12px 16px;
    background-color: #f9f9f9;
    border-radius: 4px;
    margin-top: 2px;
    font-size: 14px;
    color: #333;
    line-height: 1.5;
    max-width: 100%;
    box-sizing: border-box;
}

.info-box strong {
    display: block;
    margin-bottom: 4px;
    color: #000;
}

.info-box .sub-info {
    color: #0066cc;
    font-weight: 500;
}
